import { cookies, headers } from 'next/headers'

function preferredLanguageFromAcceptLanguage(
  acceptLanguage: string | null
): string {
  if (!acceptLanguage?.trim()) {
    return 'Not specified'
  }

  const ranges = acceptLanguage.split(',').map((part) => {
    const [tag, ...params] = part.trim().split(';')
    const qPart = params.find((p) => p.trim().toLowerCase().startsWith('q='))
    const q = qPart ? Number.parseFloat(qPart.split('=')[1]?.trim() ?? '1') : 1
    return {
      tag: tag.trim(),
      q: Number.isFinite(q) ? q : 0,
    }
  })

  ranges.sort((a, b) => b.q - a.q)
  const best = ranges[0]?.tag
  return best && best.length > 0 ? best : acceptLanguage.trim()
}

export async function ThemeAndLanguagePreferences() {
  const cookieStore = await cookies()
  const headersList = await headers()

  const themeCookie = cookieStore.get('theme')
  const theme = themeCookie?.value ?? 'light'

  const acceptLanguage = headersList.get('accept-language')
  const preferredLanguage = preferredLanguageFromAcceptLanguage(acceptLanguage)

  return (
    <dl>
      <dt>Theme</dt>
      <dd>{theme}</dd>
      <dt>Preferred language</dt>
      <dd>{preferredLanguage}</dd>
    </dl>
  )
}

